from ortools.sat.python import cp_model
import json

def solve_facility_location():
    model = cp_model.CpModel()

    I = [1, 2, 3]
    J = [1, 2, 3, 4, 5, 6, 7, 8]

    construction_cost = {
        1: 2150,
        2: 1900, 
        3: 2400
    }

    demand = {
        1: 90000,
        2: 110000,
        3: 95000,
        4: 120000,
        5: 80000,
        6: 135000,
        7: 100000,
        8: 90000
    }

    shipping_cost = {
        (1, 1): 65, (2, 1): 85, (3, 1): 70,
        (1, 2): 55, (2, 2): 50, (3, 2): 80,
        (1, 3): 75, (2, 3): 90, (3, 3): 55,
        (1, 4): 90, (2, 4): 70, (3, 4): 75,
        (1, 5): 40, (2, 5): 100, (3, 5): 70,
        (1, 6): 85, (2, 6): 60, (3, 6): 65,
        (1, 7): 70, (2, 7): 90, (3, 7): 60,
        (1, 8): 70, (2, 8): 80, (3, 8): 95
    }

    open_vars = {}
    for i in I:
        open_vars[i] = model.NewBoolVar(f"open_{i}")

    assign_vars = {}
    for i in I:
        for j in J:
            assign_vars[(i, j)] = model.NewBoolVar(f"assign_{i}_{j}")

    for j in J:
        model.Add(sum(assign_vars[(i, j)] for i in I) == 1)

    for i in I:
        for j in J:
            model.Add(assign_vars[(i, j)] <= open_vars[i])

    construction_cost_expr = sum(construction_cost[i] * 1000 * open_vars[i] for i in I)

    transportation_cost_expr = sum(
        demand[j] * shipping_cost[(i, j)] * assign_vars[(i, j)] 
        for i in I for j in J
    )

    total_cost_expr = construction_cost_expr + transportation_cost_expr

    model.Minimize(total_cost_expr)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 0

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_cost = solver.ObjectiveValue()

        warehouses_built = [int(solver.Value(open_vars[i])) for i in I]

        assignments = []
        for j in J:
            assignment_vector = [int(solver.Value(assign_vars[(i, j)])) for i in I]
            assignments.append(assignment_vector)

        print(json.dumps({
            "total_cost": total_cost / 1000,
            "warehouses_built": warehouses_built,
            "assignments": assignments
        }))
    else:
        print(json.dumps({
            "total_cost": 0,
            "warehouses_built": [0, 0, 0],
            "assignments": [[0,0,0] for _ in J]
        }))

if __name__ == "__main__":
    solve_facility_location()
